function randomWalkers(startPoint, segLen, maxSteps = 1000) {
	const seed = random();
	const noiseScale = 0.1;
	const makeWalker = (dAng, sgn) => function*() {
		let p = startPoint.copy();
		let q = startPoint.copy();
		const hgt = (x, y) => noise(x * noiseScale, y * noiseScale, seed);
		const nrm = (x, y) => createVector(1, 0).rotate(hgt(x, y) * TAU)
		//createVector (gradNoise(x*noiseScale,y*noiseScale,seed),gradNoise(x*noiseScale,y*noiseScale,seed+100)).normalize();
		//createVector (hgt(x+0.01,y)-hgt(x-0.01,y), hgt(x, y+0.01)-hgt(x, y-0.01)).normalize();
		for (let i = 0; i < maxSteps; i++) {
			const v = nrm(q.x, q.y).rotate(dAng);
			q.add(v)
			p.add(v.mult(segLen))
			yield p;
		}
	}
	let angSeed = random(TAU);
	return [makeWalker(angSeed, 1)(), makeWalker(angSeed + PI, 1)()]
}

