function varyColor(c, amt = 0.1) {
	let h = hue(c);
	let s = saturation(c);
	let b = brightness(c);
	return color(constrain(h + random(-amt, amt), 0, 1), constrain(s + random(-amt, amt), 0, 1), constrain(b + random(-amt, amt), 0, 1))
}

function genCurve(startPoint = null) {
	var p = startPoint || randomPoint();
	let [fwd, bck] = randomWalkers(p, 20);
	let pts = [p];
	for (let q of fwd) {
		pts.push(q.copy())
		if (q.x < 0 || q.y < 0 || q.x > width || q.y > height) break;
	}
	pts.reverse();
	for (let q of bck) {
		pts.push(q.copy())
		if (q.x < 0 || q.y < 0 || q.x > width || q.y > height) break;
	}
	return pts;
}

