//
// Orientation of triangle a - b - c 
//
function orient(a, b, c) {
	return Math.sign(b.x * (c.y - a.y) + c.x * (a.y - b.y) + a.x * (b.y - c.y))
}


function orientation(p, q, r) {
  let val = (q.y - p.y) * (r.x - q.x) - (q.x - p.x) * (r.y - q.y);
  if (abs(val) < 1e-10) return 0; // collinear
  return (val > 0) ? 1 : 2; // 1: clockwise, 2: counterclockwise
}


//
// Returns true iff segments a-b and c-d intersect
//
function segmentsIntersect(a, b, c, d) {
  return (
    Math.abs(orient(a, b, c) - orient(a, b, d)) >= 1 &&
    Math.abs(orient(c, d, a) - orient(c, d, b)) >= 1
  );
}

//
// If infinite lines passing through a-b and through c-d intersect, then 
// returns the intersection point.
//
function lineIntersection (a,b,c,d) {
	let p1 = a, v1 = b.copy().sub(a), p2 = c, v2 = d.copy().sub(c);
  const D = v1.x * v2.y - v1.y * v2.x;
	if (D == 0) throw "parallel lines";
  const t = (v2.y * (p2.x - p1.x) + p1.y * v2.x - p2.y * v2.x) / D;
  return createVector(p1.x + v1.x * t, p1.y + v1.y * t);
}

//
// Returns true iff p inside polygon poly
//
function pointInPolygon(p, poly) {
  // The y coordinate of p
  const py = p.y;
  // 1d orientation of a point's y with respect to py
  const yOrient = (p) => Math.sign(p.y - py);
  // Number of vertices
  const n = poly.length;
  // Previous point (the last of poly) and its y orientation
  let prev = poly[n - 1];
  let prevYOr = yOrient(prev);
  // Intersection counter
  let count = 0;
  // Test all vertices
  for (let i = 0; i < n; i++) {
    var q = poly[i];
    const yOr = yOrient(q);
    if (Math.abs(yOr - prevYOr) >= 1) {
      // Point within y range of segment prev-q
      const pOr = orient(prev, q, p);
      const far = createVector(Infinity, py); // Point to the right of segment prev-q
      const farOr = orient(prev, q, far);
      if (Math.abs(pOr - farOr) == 2) {
        // segment p-far crosses segment prev-q
        if (yOr == 0) {
          // Intersection at q ?
          // Test if next endPoint on opposite y orientations
          const next = poly[(i + 1) % n];
          const nextYOr = yOrient(next);
          if (Math.abs(nextYOr - prevYOr) == 2) count++;
        } else {
          if (prevYOr != 0) count++; // Ignore intersections passing through prev
        }
      }
    }
    prevYOr = yOr;
    prev = q;
  }
  return count % 2 == 1;
}

function polygonArea(poly) {
  let {x:px, y:py} = poly[poly.length - 1];
  let area = 0;
  for (let {x,y} of poly) {
    area += (px - x) * (y + py);
    [px, py] = [x, y];
  }
  return area / 2;
}

function curvePolygonSplit (curve, poly) {
	if (pointInPolygon (curve[0],poly)) throw "Curve must start outside the polygon";
	let polygonMbr = new MBR(); 
	for (let p of poly) polygonMbr.add(p); 
	for (let p of curve) polygonMbr.add(p);
	polygonMbr.expand(20)
	let npoly = poly.length;
	let sz = polygonMbr.size();
	let searchDS = new SearchDS (polygonMbr.min.x, polygonMbr.min.y, sz.x, sz.y);
	for (let i = 0; i < npoly; i++) {
		let j = (i+1) % npoly;
		let obj = {i, j};
		var mbr = new MBR(poly[i], poly[j])
		searchDS.add(mbr,obj)	
	}
	let intersections = [];
	let ncurve = curve.length;
	for (let k = 0; k+1 < ncurve && intersections.length < 2; k++) {
		let [a,b] = [curve[k], curve[k+1]]
		var mbr = new MBR(a,b);
		for (let {i,j} of searchDS.valuesInMbr(mbr)) {
			let [c,d] = [poly[i],poly[j]];
			if (segmentsIntersect(a,b,c,d)) {
				var p = lineIntersection (a,b,c,d);
				intersections.push({k,i,j,p})
				if (intersections.length == 2) break;
			}
		}
	}
	if (intersections.length == 2) {
		let {i:i1,j:j1,k:k1,p:p1} = intersections[0];
		let {i:i2,j:j2,k:k2,p:p2} = intersections[1];
		let part1 = [p1];
		for (let k = k1+1; k < k2; k++) {
			part1.push(curve[k])
		}
		part1.push(p2);
		var count = 0;
		for (let i = j2; i != i1 && count++ < 10000; i = (i+1) % npoly) {
			part1.push(poly[i]);
		}
		part1.push(poly[i1]);
		if (count > 10000) throw "Cant close circulation"
		let part2 = [p2]; 
		for (let k = k2-1; k > k1; k--) {
			part2.push(curve[k])
		}
		part2.push(p1);
		count = 0;
		for (let i = j1; i != j2 && count++ < 10000; i = (i+1) % npoly) {
			part2.push(poly[i])
		}
		part2.push(poly[j2])
		return [part1,part2]
	}
	return [];
}

