// Compute the distance from point p to the line segment from v to w.
function pointToSegmentDistance(p, v, w) {
  let l2 = p5.Vector.sub(w, v).magSq();
  if (l2 === 0) return p5.Vector.dist(p, v);
  var t = constrain(p5.Vector.sub(p, v).dot(p5.Vector.sub(w, v)) / l2, 0, 1);
  let projection = p5.Vector.add(v, p5.Vector.sub(w, v).mult(t));
  return p5.Vector.dist(p, projection);
}

// Returns the smallest distance from point to any edge of the polygon.
function pointToPolygonDistance(point, polygon) {
  let minDist = Infinity;
  for (let i = 0; i < polygon.length; i++) {
    var v = polygon[i];
    let w = polygon[(i + 1) % polygon.length];
    let d = pointToSegmentDistance(point, v, w);
    if (d < minDist) minDist = d;
  }
  return minDist;
}

// Finds a point inside the polygon that is as far as possible from its edges.
function findDeepestInteriorPoint(polygon) {
  // Compute the bounding box of the polygon.
  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
  for (let p of polygon) {
    if (p.x < minX) minX = p.x;
    if (p.y < minY) minY = p.y;
    if (p.x > maxX) maxX = p.x;
    if (p.y > maxY) maxY = p.y;
  }

  // Start with the center of the bounding box.
  let bestPoint = createVector((minX + maxX) / 2, (minY + maxY) / 2);
  let bestDistance = pointInPolygon(bestPoint, polygon) ? pointToPolygonDistance(bestPoint, polygon) : 0;

  // Begin hill-climbing search with an initial step size.
  let step = Math.min(maxX - minX, maxY - minY) / 2;
  while (step > 1) { // Continue until step is sufficiently small.
    let foundBetter = false;
    // Examine candidate points in a grid around the current bestPoint.
    for (let dx = -step; dx <= step; dx += step) {
      for (let dy = -step; dy <= step; dy += step) {
        let candidate = createVector(bestPoint.x + dx, bestPoint.y + dy);
        if (pointInPolygon(candidate, polygon)) {
          var d = pointToPolygonDistance(candidate, polygon);
          if (d > bestDistance) {
            bestDistance = d;
            bestPoint = candidate;
            foundBetter = true;
          }
        }
      }
    }
    if (!foundBetter) {
      step /= 2; // Refine the search.
    }
  }

  return bestPoint;
}


