// Helper: Check if the chord from polygon[i] to polygon[j] is a valid diagonal (i.e. lies inside).
function isDiagonal(i, j, polygon) {
  var n = polygon.length;
  // Adjacent vertices (or the same) do not form a diagonal.
  if ((j === (i + 1) % n) || (i === (j + 1) % n)) return false;

  var a = polygon[i];
  var b = polygon[j];

  // Check against all edges (skip edges incident to a or b).
  for (let k = 0; k < n; k++) {
    let kNext = (k + 1) % n;
    if (k === i || k === j || kNext === i || kNext === j) continue;
    if (segmentsIntersect(a, b, polygon[k], polygon[kNext])) return false;
  }

  // As an extra check, ensure the chord's midpoint is inside.
  let mid = createVector((a.x + b.x) / 2, (a.y + b.y) / 2);
  if (!pointInPolygon(mid, polygon)) return false;

  return true;
}

// Main function: Finds a chord that splits the polygon into two parts of nearly equal area,
// and returns the midpoint of that chord as a good interior point.
function findSplitChordInteriorPoint(polygon) {
  var n = polygon.length;

  // For triangles or degenerate polygons, return the centroid.
  if (n < 4) {
    let cx = 0, cy = 0;
    for (let p of polygon) {
      cx += p.x;
      cy += p.y;
    }
    return createVector(cx / n, cy / n);
  }

  const totalArea = polygonArea(polygon);
  let bestDiff = Infinity;
  let bestMidpoint = null;

  // Consider every pair of vertices (that are not adjacent).
  for (let i = 0; i < n; i++) {
    for (let j = i + 2; j < n; j++) {
      // Skip if chord would be an edge (e.g. first and last vertex).
      if (i === 0 && j === n - 1) continue;

      if (!isDiagonal(i, j, polygon)) continue;

      // Form the two subpolygons split by the chord.
      let poly1 = [];
      for (let k = i; k <= j; k++) {
        poly1.push(polygon[k]);
      }
      let poly2 = [];
      // From vertex j back to vertex i (wrapping around).
      for (let k = j; k < n; k++) {
        poly2.push(polygon[k]);
      }
      for (let k = 0; k <= i; k++) {
        poly2.push(polygon[k]);
      }

      let area1 = polygonArea(poly1);
      let area2 = polygonArea(poly2);
      let diff = abs(area1 - area2);

      // Look for the chord that minimizes the area difference.
      if (diff < bestDiff) {
        bestDiff = diff;
        bestMidpoint = createVector(
          (polygon[i].x + polygon[j].x) / 2,
          (polygon[i].y + polygon[j].y) / 2
        );
      }
    }
  }

  // Fallback: if no valid chord was found, return the centroid.
  if (!bestMidpoint) {
    var cx = 0, cy = 0;
    for (let p of polygon) { cx += p.x; cy += p.y; }
    return createVector(cx / n, cy / n);
  }

  return bestMidpoint;
}

